    def forward(self, x):
        #return self.extract_features_as_mxnet(x)
        return self.extract_features_after_stage(x)

    def orchestrate(self, x, use_end_of_stage):
        if use_end_of_stage:
            return self.extract_features_after_stage(x)
        else:
            return self.extract_features_as_mxnet(x)


    #Based on the forward function() I implemented this extract_features() function. It has the job of extracting the feature maps exactly as the authors did in their mxnet implementation.
    # Dimensions are: {4: (1, 128, 160, 160), 8: (1, 256, 80, 80), 16: (1, 512, 40, 40), 32: (1, 2048, 20, 20)} when returning stage2_unit1_relu2, stage3_unit1_relu2, stage4_unit1_relu2, relu1
    def extract_features_as_mxnet(self, x):

        x = self.bn_data(x)
        x = F.pad(x, (3, 3, 3, 3))
        x = self.conv0(x)
        x = self.bn0(x)
        x = F.relu(x)
        x = F.pad(x, (1, 1, 1, 1), value=float('-inf'))
        x, pooling0_idx = F.max_pool2d(x, kernel_size=(3, 3), stride=(2, 2), padding=0,
                                              ceil_mode=False, return_indices=True)
        x = self.stage1_unit1_bn1(x)
        x = F.relu(x)
        stage1_unit1_conv1 = self.stage1_unit1_conv1(x)
        stage1_unit1_sc = self.stage1_unit1_sc(x)
        x = self.stage1_unit1_bn2(stage1_unit1_conv1)
        x = F.relu(x)
        x = F.pad(x, (1, 1, 1, 1))
        x = self.stage1_unit1_conv2(x)
        x = self.stage1_unit1_bn3(x)
        x = F.relu(x)
        x = self.stage1_unit1_conv3(x)
        plus0 = x + stage1_unit1_sc
        x = self.stage1_unit2_bn1(plus0)
        x = F.relu(x)
        x = self.stage1_unit2_conv1(x)
        x = self.stage1_unit2_bn2(x)
        x = F.relu(x)
        x = F.pad(x, (1, 1, 1, 1))
        x = self.stage1_unit2_conv2(x)
        x = self.stage1_unit2_bn3(x)
        x = F.relu(x)
        x = self.stage1_unit2_conv3(x)
        plus1 = x + plus0
        x = self.stage1_unit3_bn1(plus1)
        x = F.relu(x)
        x = self.stage1_unit3_conv1(x)
        x = self.stage1_unit3_bn2(x)
        x = F.relu(x)
        x = F.pad(x, (1, 1, 1, 1))
        x = self.stage1_unit3_conv2(x)
        x = self.stage1_unit3_bn3(x)
        x = F.relu(x)
        x = self.stage1_unit3_conv3(x)
        plus2 = x + plus1
        x = self.stage2_unit1_bn1(plus2)
        x = F.relu(x)
        stage2_unit1_conv1 = self.stage2_unit1_conv1(x)
        stage2_unit1_sc = self.stage2_unit1_sc(x)
        x = self.stage2_unit1_bn2(stage2_unit1_conv1)
        #Will be returned
        stage2_unit1_relu2 = F.relu(x)
        x = F.pad(stage2_unit1_relu2, (1, 1, 1, 1))
        x = self.stage2_unit1_conv2(x)
