        x = F.relu(x)
        x = self.stage2_unit4_conv3(x)
        plus6 = x + plus5
        x = self.stage3_unit1_bn1(plus6)
        x = F.relu(x)
        stage3_unit1_conv1 = self.stage3_unit1_conv1(x)
        stage3_unit1_sc = self.stage3_unit1_sc(x)
