        x = self.stage3_unit6_conv2(x)
        x = self.stage3_unit6_bn3(x)
        x = F.relu(x)
        x = self.stage3_unit6_conv3(x)
        plus12 = x + plus11
        x = self.stage4_unit1_bn1(plus12)
        x = F.relu(x)
        stage4_unit1_conv1 = self.stage4_unit1_conv1(x)
        stage4_unit1_sc = self.stage4_unit1_sc(x)
        x = self.stage4_unit1_bn2(stage4_unit1_conv1)
        # Will be returned
        stage4_unit1_relu2 = F.relu(x)
        x = F.pad(stage4_unit1_relu2, (1, 1, 1, 1))
